import React from 'react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer } from 'recharts';
import { RIASECScores } from '../types';
import { RIASEC_INFO } from '../constants';

interface CareerChartProps {
  scores: RIASECScores;
}

const CareerChart: React.FC<CareerChartProps> = ({ scores }) => {
  const data = [
    { subject: RIASEC_INFO.R.label, A: scores.R, fullMark: 10 },
    { subject: RIASEC_INFO.I.label, A: scores.I, fullMark: 10 },
    { subject: RIASEC_INFO.A.label, A: scores.A, fullMark: 10 },
    { subject: RIASEC_INFO.S.label, A: scores.S, fullMark: 10 },
    { subject: RIASEC_INFO.E.label, A: scores.E, fullMark: 10 },
    { subject: RIASEC_INFO.C.label, A: scores.C, fullMark: 10 },
  ];

  return (
    <div className="w-full h-[300px] md:h-[400px]">
      <ResponsiveContainer width="100%" height="100%">
        <RadarChart cx="50%" cy="50%" outerRadius="80%" data={data}>
          <PolarGrid stroke="#e2e8f0" />
          <PolarAngleAxis dataKey="subject" tick={{ fill: '#475569', fontSize: 12 }} />
          <Radar
            name="الميول المهنية"
            dataKey="A"
            stroke="#059669"
            fill="#10b981"
            fillOpacity={0.6}
          />
        </RadarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default CareerChart;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import CareerChart from './components/CareerChart';
import { QUESTIONS, SESSIONS, RIASEC_INFO } from './constants';
import { RIASECScores, ChatMessage, RIASECKey } from './types';
import { getCareerGuidance, getInitialAnalysis } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('home');
  const [quizStarted, setQuizStarted] = useState(false);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [scores, setScores] = useState<RIASECScores | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState('');
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [currentInput, setCurrentInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);

  // Calculate scores from answers
  const calculateResult = async () => {
    const newScores: RIASECScores = { R: 0, I: 0, A: 0, S: 0, E: 0, C: 0 };
    Object.entries(answers).forEach(([id, val]) => {
      const question = QUESTIONS.find(q => q.id === parseInt(id));
      if (question) {
        newScores[question.category] += val;
      }
    });
    setScores(newScores);
    setQuizStarted(false);

    // Initial AI analysis
    const analysis = await getInitialAnalysis(newScores);
    setAiAnalysis(analysis);
  };

  const handleSendMessage = async () => {
    if (!currentInput.trim() || !scores) return;

    const userMsg: ChatMessage = { role: 'user', text: currentInput };
    setChatMessages(prev => [...prev, userMsg]);
    setCurrentInput('');
    setIsChatLoading(true);

    const botResponse = await getCareerGuidance(scores, currentInput);
    setChatMessages(prev => [...prev, { role: 'model', text: botResponse }]);
    setIsChatLoading(false);
  };

  const renderHome = () => (
    <div className="space-y-12 py-6">
      <section className="text-center space-y-4 max-w-3xl mx-auto">
        <h2 className="text-4xl font-extrabold text-slate-900 md:text-5xl">برنامج "بوصلتي" للتمكين المهني</h2>
        <p className="text-lg text-slate-600 leading-relaxed">
          نحن ندمج بين نظريات الإرشاد المهني الكلاسيكية (هولاند وسوبر) وبين ذكاء المستقبل لمساعدتك في رسم طريقك الأكاديمي والمهني بوعي وثقة.
        </p>
        <button 
          onClick={() => setActiveTab('quiz')}
          className="mt-6 bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-full font-bold shadow-lg transition-all transform hover:scale-105"
        >
          ابدأ رحلة الاستكشاف الآن
        </button>
      </section>

      <div className="grid md:grid-cols-3 gap-6">
        {[
          { title: "التشخيص الذكي", desc: "تحليل الميول والقدرات باستخدام الذكاء الاصطناعي.", icon: "🤖" },
          { title: "المواءمة المهنية", desc: "ربط سماتك الشخصية ببيانات سوق العمل الحديث.", icon: "🔗" },
          { title: "التوجيه التفاعلي", desc: "جلسات إرشادية رقمية تحاكي بيئات العمل الواقعية.", icon: "💡" }
        ].map((item, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow text-center">
            <span className="text-4xl block mb-4">{item.icon}</span>
            <h3 className="text-xl font-bold text-slate-800 mb-2">{item.title}</h3>
            <p className="text-slate-500 text-sm leading-relaxed">{item.desc}</p>
          </div>
        ))}
      </div>
    </div>
  );

  const renderQuiz = () => {
    if (scores) {
      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <div className="grid lg:grid-cols-2 gap-8 items-start">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-2xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                <span className="text-emerald-500">📊</span> هويتك المهنية (RIASEC)
              </h3>
              <CareerChart scores={scores} />
              <div className="grid grid-cols-2 gap-4 mt-6">
                {(Object.keys(RIASEC_INFO) as RIASECKey[]).map((key) => (
                  <div key={key} className="p-3 rounded-xl border border-slate-50 bg-slate-50/50">
                    <div className="text-xs font-bold mb-1" style={{ color: RIASEC_INFO[key].color }}>
                      {RIASEC_INFO[key].label}
                    </div>
                    <div className="text-lg font-black text-slate-700">{scores[key]} / 10</div>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <div className="bg-emerald-50 border border-emerald-100 p-8 rounded-3xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 text-4xl opacity-10">✨</div>
                <h4 className="text-emerald-800 font-bold text-xl mb-4">تحليل الخبير الذكي</h4>
                <p className="text-emerald-900/80 leading-relaxed whitespace-pre-wrap">{aiAnalysis}</p>
              </div>

              <div className="bg-slate-900 p-6 rounded-3xl text-white shadow-xl">
                <h4 className="font-bold text-lg mb-4 flex items-center gap-2">
                  <span className="animate-pulse w-2 h-2 rounded-full bg-emerald-400"></span>
                  ناقش مستقبلك مع "بوصلتي"
                </h4>
                <div className="h-64 overflow-y-auto mb-4 space-y-4 p-2 custom-scrollbar">
                  {chatMessages.length === 0 && (
                    <p className="text-slate-500 text-sm text-center italic">اسألني عن التخصصات التي تناسب نتائجك...</p>
                  )}
                  {chatMessages.map((m, i) => (
                    <div key={i} className={`flex ${m.role === 'user' ? 'justify-start' : 'justify-end'}`}>
                      <div className={`max-w-[85%] px-4 py-2 rounded-2xl text-sm ${m.role === 'user' ? 'bg-slate-800 border border-slate-700' : 'bg-emerald-600 text-white shadow-lg'}`}>
                        {m.text}
                      </div>
                    </div>
                  ))}
                  {isChatLoading && <div className="text-xs text-emerald-400 animate-pulse">المستشار يفكر...</div>}
                </div>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={currentInput}
                    onChange={(e) => setCurrentInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                    placeholder="اكتب سؤالك هنا..."
                    className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                  />
                  <button 
                    onClick={handleSendMessage}
                    disabled={isChatLoading}
                    className="bg-emerald-500 hover:bg-emerald-400 p-2 rounded-xl transition-colors disabled:opacity-50"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 5l7 7-7 7M5 5l7 7-7 7"></path></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>
          <button 
            onClick={() => {setScores(null); setAnswers({}); setChatMessages([]); setAiAnalysis('');}}
            className="text-slate-400 text-sm hover:text-emerald-500 underline"
          >
            إعادة المقياس مرة أخرى
          </button>
        </div>
      );
    }

    if (!quizStarted) {
      return (
        <div className="max-w-2xl mx-auto text-center space-y-8 py-12">
          <div className="text-6xl">📝</div>
          <h3 className="text-3xl font-bold text-slate-800">مقياس الميول المهنية الذكي</h3>
          <p className="text-slate-600">
            يتكون هذا المقياس من مجموعة من الأنشطة والاهتمامات. يرجى اختيار مدى حبك أو رغبتك في القيام بكل نشاط بكل صراحة.
            لا توجد إجابات صحيحة أو خاطئة، المهم هو ما تشعر به فعلاً.
          </p>
          <div className="bg-white p-6 rounded-2xl border border-slate-100 flex items-center gap-4 text-right">
            <div className="bg-blue-100 p-3 rounded-xl text-blue-600 font-bold">5 دقائق</div>
            <p className="text-sm text-slate-500">وقت التقييم التقريبي للحصول على أدق النتائج.</p>
          </div>
          <button 
            onClick={() => setQuizStarted(true)}
            className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-4 rounded-2xl font-bold text-lg shadow-xl"
          >
            ابدأ التقييم الآن
          </button>
        </div>
      );
    }

    return (
      <div className="max-w-3xl mx-auto space-y-6">
        <div className="flex justify-between items-center px-4">
          <span className="text-xs font-bold text-slate-400">تقدمك: {Math.round((Object.keys(answers).length / QUESTIONS.length) * 100)}%</span>
          <div className="w-48 h-2 bg-slate-200 rounded-full overflow-hidden">
             <div 
              className="h-full bg-emerald-500 transition-all duration-300" 
              style={{ width: `${(Object.keys(answers).length / QUESTIONS.length) * 100}%` }}
            ></div>
          </div>
        </div>
        {QUESTIONS.map((q) => (
          <div key={q.id} className="bg-white p-6 md:p-8 rounded-3xl border border-slate-100 shadow-sm space-y-4">
            <p className="text-xl font-bold text-slate-800 leading-tight">{q.text}</p>
            <div className="grid grid-cols-5 gap-2">
              {[1, 2, 3, 4, 5].map((val) => (
                <button
                  key={val}
                  onClick={() => setAnswers(prev => ({ ...prev, [q.id]: val }))}
                  className={`py-3 rounded-xl text-sm font-bold transition-all border-2 ${
                    answers[q.id] === val 
                    ? 'bg-emerald-600 border-emerald-600 text-white scale-105 shadow-md' 
                    : 'bg-white border-slate-100 text-slate-400 hover:border-emerald-200'
                  }`}
                >
                  {val === 5 ? 'جداً' : val === 1 ? 'أبداً' : ''}
                  <span className="block text-xs mt-1">{val}</span>
                </button>
              ))}
            </div>
          </div>
        ))}
        <button 
          onClick={calculateResult}
          disabled={Object.keys(answers).length < QUESTIONS.length}
          className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 text-white py-4 rounded-2xl font-bold text-lg transition-all"
        >
          {Object.keys(answers).length < QUESTIONS.length ? 'يرجى إكمال جميع الأسئلة' : 'عرض النتائج والتحليل الذكي'}
        </button>
      </div>
    );
  };

  const renderSessions = () => (
    <div className="space-y-10">
      <div className="text-center max-w-2xl mx-auto space-y-4">
        <h2 className="text-3xl font-bold text-slate-900">الخطة الإرشادية المتكاملة</h2>
        <p className="text-slate-600">جدول الجلسات التفصيلية الذي يرافقك طوال الفصل الدراسي لضمان وصولك لمرحلة "الهوية المهنية" الواضحة.</p>
      </div>
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
        {SESSIONS.map((session) => (
          <div key={session.id} className="group bg-white p-8 rounded-3xl border border-slate-100 shadow-sm hover:shadow-xl transition-all relative overflow-hidden">
            <div className="absolute -top-4 -left-4 w-24 h-24 bg-emerald-50 rounded-full group-hover:scale-150 transition-transform duration-500 opacity-50"></div>
            <div className="relative">
              <div className="flex justify-between items-start mb-6">
                <span className="text-4xl">{session.icon}</span>
                <span className="bg-emerald-100 text-emerald-700 text-xs font-black px-3 py-1 rounded-full">الجلسة {session.id}</span>
              </div>
              <h3 className="text-xl font-bold text-slate-800 mb-3">{session.title}</h3>
              <p className="text-slate-500 text-sm mb-4 leading-relaxed">{session.description}</p>
              <div className="pt-4 border-t border-slate-50">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">الهدف الأساسي</p>
                <p className="text-sm font-semibold text-emerald-600">{session.objective}</p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {activeTab === 'home' && renderHome()}
      {activeTab === 'quiz' && renderQuiz()}
      {activeTab === 'sessions' && renderSessions()}
    </Layout>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import CareerChart from './components/CareerChart';
import { QUESTIONS, SESSIONS, RIASEC_INFO } from './constants';
import { RIASECScores, ChatMessage, RIASECKey } from './types';
import { getCareerGuidance, getInitialAnalysis } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('home');
  const [quizStarted, setQuizStarted] = useState(false);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [scores, setScores] = useState<RIASECScores | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState('');
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [currentInput, setCurrentInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);

  // Calculate scores from answers
  const calculateResult = async () => {
    const newScores: RIASECScores = { R: 0, I: 0, A: 0, S: 0, E: 0, C: 0 };
    Object.entries(answers).forEach(([id, val]) => {
      const question = QUESTIONS.find(q => q.id === parseInt(id));
      if (question) {
        newScores[question.category] += val;
      }
    });
    setScores(newScores);
    setQuizStarted(false);

    // Initial AI analysis
    const analysis = await getInitialAnalysis(newScores);
    setAiAnalysis(analysis);
  };

  const handleSendMessage = async () => {
    if (!currentInput.trim() || !scores) return;

    const userMsg: ChatMessage = { role: 'user', text: currentInput };
    setChatMessages(prev => [...prev, userMsg]);
    setCurrentInput('');
    setIsChatLoading(true);

    const botResponse = await getCareerGuidance(scores, currentInput);
    setChatMessages(prev => [...prev, { role: 'model', text: botResponse }]);
    setIsChatLoading(false);
  };

  const renderHome = () => (
    <div className="space-y-12 py-6">
      <section className="text-center space-y-4 max-w-3xl mx-auto">
        <h2 className="text-4xl font-extrabold text-slate-900 md:text-5xl">برنامج "بوصلتي" للتمكين المهني</h2>
        <p className="text-lg text-slate-600 leading-relaxed">
          نحن ندمج بين نظريات الإرشاد المهني الكلاسيكية (هولاند وسوبر) وبين ذكاء المستقبل لمساعدتك في رسم طريقك الأكاديمي والمهني بوعي وثقة.
        </p>
        <button 
          onClick={() => setActiveTab('quiz')}
          className="mt-6 bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-full font-bold shadow-lg transition-all transform hover:scale-105"
        >
          ابدأ رحلة الاستكشاف الآن
        </button>
      </section>

      <div className="grid md:grid-cols-3 gap-6">
        {[
          { title: "التشخيص الذكي", desc: "تحليل الميول والقدرات باستخدام الذكاء الاصطناعي.", icon: "🤖" },
          { title: "المواءمة المهنية", desc: "ربط سماتك الشخصية ببيانات سوق العمل الحديث.", icon: "🔗" },
          { title: "التوجيه التفاعلي", desc: "جلسات إرشادية رقمية تحاكي بيئات العمل الواقعية.", icon: "💡" }
        ].map((item, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow text-center">
            <span className="text-4xl block mb-4">{item.icon}</span>
            <h3 className="text-xl font-bold text-slate-800 mb-2">{item.title}</h3>
            <p className="text-slate-500 text-sm leading-relaxed">{item.desc}</p>
          </div>
        ))}
      </div>
    </div>
  );

  const renderQuiz = () => {
    if (scores) {
      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <div className="grid lg:grid-cols-2 gap-8 items-start">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-2xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                <span className="text-emerald-500">📊</span> هويتك المهنية (RIASEC)
              </h3>
              <CareerChart scores={scores} />
              <div className="grid grid-cols-2 gap-4 mt-6">
                {(Object.keys(RIASEC_INFO) as RIASECKey[]).map((key) => (
                  <div key={key} className="p-3 rounded-xl border border-slate-50 bg-slate-50/50">
                    <div className="text-xs font-bold mb-1" style={{ color: RIASEC_INFO[key].color }}>
                      {RIASEC_INFO[key].label}
                    </div>
                    <div className="text-lg font-black text-slate-700">{scores[key]} / 10</div>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <div className="bg-emerald-50 border border-emerald-100 p-8 rounded-3xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 text-4xl opacity-10">✨</div>
                <h4 className="text-emerald-800 font-bold text-xl mb-4">تحليل الخبير الذكي</h4>
                <p className="text-emerald-900/80 leading-relaxed whitespace-pre-wrap">{aiAnalysis}</p>
              </div>

              <div className="bg-slate-900 p-6 rounded-3xl text-white shadow-xl">
                <h4 className="font-bold text-lg mb-4 flex items-center gap-2">
                  <span className="animate-pulse w-2 h-2 rounded-full bg-emerald-400"></span>
                  ناقش مستقبلك مع "بوصلتي"
                </h4>
                <div className="h-64 overflow-y-auto mb-4 space-y-4 p-2 custom-scrollbar">
                  {chatMessages.length === 0 && (
                    <p className="text-slate-500 text-sm text-center italic">اسألني عن التخصصات التي تناسب نتائجك...</p>
                  )}
                  {chatMessages.map((m, i) => (
                    <div key={i} className={`flex ${m.role === 'user' ? 'justify-start' : 'justify-end'}`}>
                      <div className={`max-w-[85%] px-4 py-2 rounded-2xl text-sm ${m.role === 'user' ? 'bg-slate-800 border border-slate-700' : 'bg-emerald-600 text-white shadow-lg'}`}>
                        {m.text}
                      </div>
                    </div>
                  ))}
                  {isChatLoading && <div className="text-xs text-emerald-400 animate-pulse">المستشار يفكر...</div>}
                </div>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={currentInput}
                    onChange={(e) => setCurrentInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                    placeholder="اكتب سؤالك هنا..."
                    className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                  />
                  <button 
                    onClick={handleSendMessage}
                    disabled={isChatLoading}
                    className="bg-emerald-500 hover:bg-emerald-400 p-2 rounded-xl transition-colors disabled:opacity-50"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 5l7 7-7 7M5 5l7 7-7 7"></path></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>
          <button 
            onClick={() => {setScores(null); setAnswers({}); setChatMessages([]); setAiAnalysis('');}}
            className="text-slate-400 text-sm hover:text-emerald-500 underline"
          >
            إعادة المقياس مرة أخرى
          </button>
        </div>
      );
    }

    if (!quizStarted) {
      return (
        <div className="max-w-2xl mx-auto text-center space-y-8 py-12">
          <div className="text-6xl">📝</div>
          <h3 className="text-3xl font-bold text-slate-800">مقياس الميول المهنية الذكي</h3>
          <p className="text-slate-600">
            يتكون هذا المقياس من مجموعة من الأنشطة والاهتمامات. يرجى اختيار مدى حبك أو رغبتك في القيام بكل نشاط بكل صراحة.
            لا توجد إجابات صحيحة أو خاطئة، المهم هو ما تشعر به فعلاً.
          </p>
          <div className="bg-white p-6 rounded-2xl border border-slate-100 flex items-center gap-4 text-right">
            <div className="bg-blue-100 p-3 rounded-xl text-blue-600 font-bold">5 دقائق</div>
            <p className="text-sm text-slate-500">وقت التقييم التقريبي للحصول على أدق النتائج.</p>
          </div>
          <button 
            onClick={() => setQuizStarted(true)}
            className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-4 rounded-2xl font-bold text-lg shadow-xl"
          >
            ابدأ التقييم الآن
          </button>
        </div>
      );
    }

    return (
      <div className="max-w-3xl mx-auto space-y-6">
        <div className="flex justify-between items-center px-4">
          <span className="text-xs font-bold text-slate-400">تقدمك: {Math.round((Object.keys(answers).length / QUESTIONS.length) * 100)}%</span>
          <div className="w-48 h-2 bg-slate-200 rounded-full overflow-hidden">
             <div 
              className="h-full bg-emerald-500 transition-all duration-300" 
              style={{ width: `${(Object.keys(answers).length / QUESTIONS.length) * 100}%` }}
            ></div>
          </div>
        </div>
        {QUESTIONS.map((q) => (
          <div key={q.id} className="bg-white p-6 md:p-8 rounded-3xl border border-slate-100 shadow-sm space-y-4">
            <p className="text-xl font-bold text-slate-800 leading-tight">{q.text}</p>
            <div className="grid grid-cols-5 gap-2">
              {[1, 2, 3, 4, 5].map((val) => (
                <button
                  key={val}
                  onClick={() => setAnswers(prev => ({ ...prev, [q.id]: val }))}
                  className={`py-3 rounded-xl text-sm font-bold transition-all border-2 ${
                    answers[q.id] === val 
                    ? 'bg-emerald-600 border-emerald-600 text-white scale-105 shadow-md' 
                    : 'bg-white border-slate-100 text-slate-400 hover:border-emerald-200'
                  }`}
                >
                  {val === 5 ? 'جداً' : val === 1 ? 'أبداً' : ''}
                  <span className="block text-xs mt-1">{val}</span>
                </button>
              ))}
            </div>
          </div>
        ))}
        <button 
          onClick={calculateResult}
          disabled={Object.keys(answers).length < QUESTIONS.length}
          className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 text-white py-4 rounded-2xl font-bold text-lg transition-all"
        >
          {Object.keys(answers).length < QUESTIONS.length ? 'يرجى إكمال جميع الأسئلة' : 'عرض النتائج والتحليل الذكي'}
        </button>
      </div>
    );
  };

  const renderSessions = () => (
    <div className="space-y-10 py-6">
      <div className="text-center max-w-2xl mx-auto space-y-4 animate-in fade-in slide-in-from-top duration-700">
        <h2 className="text-3xl md:text-4xl font-black text-slate-900 leading-tight">الخطة الإرشادية المتكاملة</h2>
        <p className="text-slate-600 text-lg leading-relaxed">
          جدول الجلسات التفصيلية الذي يرافقك طوال الفصل الدراسي لضمان وصولك لمرحلة "الهوية المهنية" الواضحة.
        </p>
      </div>

      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
        {SESSIONS.map((session, index) => (
          <div 
            key={session.id} 
