                </div>
              </div>

              <h3 className="text-2xl font-black text-slate-800 mb-4 group-hover:text-emerald-700 transition-colors">
                {session.title}
              </h3>

              <p className="text-slate-500 text-sm leading-relaxed mb-8 flex-grow">
                {session.description}
              </p>

              <div className="pt-6 border-t border-slate-50 group-hover:border-emerald-100 transition-colors">
                <div className="flex items-center gap-2 mb-3">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">مخرجات الجلسة</p>
                </div>
                <p className="text-sm font-bold text-slate-700 bg-slate-50 group-hover:bg-emerald-50 p-3 rounded-xl transition-all border border-transparent group-hover:border-emerald-100">
                  {session.objective}
                </p>
              </div>

              <button className="mt-6 flex items-center justify-center gap-2 text-xs font-black text-emerald-600 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-2 group-hover:translate-y-0">
                <span>استكشف المزيد من التفاصيل</span>
                <svg className="w-4 h-4 rtl:rotate-180" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 8l4 4m0 0l-4 4m4-4H3" />
                </svg>
              </button>
            </div>
          </div>
        ))}
      </div>

      <div className="mt-12 bg-slate-900 rounded-[3rem] p-12 text-center text-white relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-emerald-500/10 rounded-full -ml-32 -mb-32 blur-3xl"></div>
        <div className="relative z-10 space-y-6">
          <h4 className="text-2xl font-bold">هل أنت مستعد للانتقال للخطوة التالية؟</h4>
          <p className="text-slate-400 max-w-xl mx-auto">كل جلسة هي لبنة في بناء مستقبلك المهني. نحن هنا لندعمك بكل الأدوات الممكنة.</p>
          <button 
            onClick={() => setActiveTab('quiz')}
            className="inline-flex items-center gap-3 bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-black px-10 py-4 rounded-2xl transition-all hover:scale-105 active:scale-95 shadow-xl shadow-emerald-500/20"
          >
            بدء التقييم الشامل
            <svg className="w-5 h-5 rtl:rotate-180" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 7l5 5m0 0l-5 5m5-5H6" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {activeTab === 'home' && renderHome()}
      {activeTab === 'quiz' && renderQuiz()}
      {activeTab === 'sessions' && renderSessions()}
    </Layout>
  );
};

