                  />
                  <button 
                    onClick={handleSendMessage}
                    disabled={isChatLoading}
                    className="bg-emerald-500 hover:bg-emerald-400 p-2 rounded-xl transition-colors disabled:opacity-50"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 5l7 7-7 7M5 5l7 7-7 7"></path></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>
          <button 
            onClick={() => {setScores(null); setAnswers({}); setChatMessages([]); setAiAnalysis('');}}
            className="text-slate-400 text-sm hover:text-emerald-500 underline"
          >
            إعادة المقياس مرة أخرى
          </button>
        </div>
      );
    }

    if (!quizStarted) {
      return (
        <div className="max-w-2xl mx-auto text-center space-y-8 py-12">
          <div className="text-6xl">📝</div>
          <h3 className="text-3xl font-bold text-slate-800">مقياس الميول المهنية الذكي</h3>
