    }

    return (
      <div className="max-w-3xl mx-auto space-y-6">
        <div className="flex justify-between items-center px-4">
          <span className="text-xs font-bold text-slate-400">تقدمك: {Math.round((Object.keys(answers).length / QUESTIONS.length) * 100)}%</span>
          <div className="w-48 h-2 bg-slate-200 rounded-full overflow-hidden">
             <div 
              className="h-full bg-emerald-500 transition-all duration-300" 
              style={{ width: `${(Object.keys(answers).length / QUESTIONS.length) * 100}%` }}
            ></div>
          </div>
        </div>
        {QUESTIONS.map((q) => (
          <div key={q.id} className="bg-white p-6 md:p-8 rounded-3xl border border-slate-100 shadow-sm space-y-4">
            <p className="text-xl font-bold text-slate-800 leading-tight">{q.text}</p>
            <div className="grid grid-cols-5 gap-2">
              {[1, 2, 3, 4, 5].map((val) => (
                <button
