            <div className="relative z-10 flex flex-col h-full">
              <div className="flex justify-between items-center mb-8">
                <div className="w-16 h-16 bg-white rounded-2xl shadow-md border border-slate-50 flex items-center justify-center text-4xl group-hover:scale-110 group-hover:rotate-3 transition-transform duration-500">
                  {session.icon}
