                    {session.id}
                  </span>
                </div>
              </div>

              <h3 className="text-2xl font-black text-slate-800 mb-4 group-hover:text-emerald-700 transition-colors">
                {session.title}
              </h3>

              <p className="text-slate-500 text-sm leading-relaxed mb-8 flex-grow">
                {session.description}
              </p>

              <div className="pt-6 border-t border-slate-50 group-hover:border-emerald-100 transition-colors">
                <div className="flex items-center gap-2 mb-3">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">مخرجات الجلسة</p>
                </div>
                <p className="text-sm font-bold text-slate-700 bg-slate-50 group-hover:bg-emerald-50 p-3 rounded-xl transition-all border border-transparent group-hover:border-emerald-100">
                  {session.objective}
                </p>
              </div>

              <button 
                onClick={() => setSelectedSession(session)}
                className="mt-6 flex items-center justify-center gap-2 text-xs font-black text-emerald-600 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-2 group-hover:translate-y-0"
              >
                <span>اقرأ المزيد</span>
                <svg className="w-4 h-4 rtl:rotate-180" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 8l4 4m0 0l-4 4m4-4H3" />
