export default App;

import { GoogleGenAI } from "@google/genai";
import { RIASECScores } from "../types";

export const getCareerGuidance = async (scores: RIASECScores, userInput: string) => {
  // إنشاء النسخة داخل الدالة لضمان استلام آخر تحديث للمفتاح من البيئة
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  const systemPrompt = `
    أنت مستشار مهني ذكي متخصص في برنامج "بوصلتي" لطلبة الصف الحادي عشر.
    بناءً على نتائج مقياس هولاند (RIASEC) التالية:
    الواقعي: ${scores.R}, البحثي: ${scores.I}, الفني: ${scores.A}, الاجتماعي: ${scores.S}, المغامر: ${scores.E}, التقليدي: ${scores.C}.

    قم بتقديم نصائح مهنية دقيقة للطلب، اقترح تخصصات جامعية مناسبة، وناقش كيف يتوافق ملفه الشخصي مع سوق العمل الحديث.
    اجعل لهجتك مشجعة، تربوية، وباللغة العربية الفصحى البسيطة. 
    تذكر أنك تخاطب طالباً في السابعة عشر من عمره.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: userInput,
      config: {
        systemInstruction: systemPrompt,
      },
    });

    return response.text || "عذراً، لم أستطع تحليل البيانات حالياً.";
  } catch (error: any) {
    console.error("Gemini Error:", error);

    if (error?.message?.includes("Requested entity was not found")) {
      return "يبدو أن هناك مشكلة في صلاحيات مفتاح التشغيل. يرجى التأكد من إعدادات الخدمة.";
    }

    return "حدث خطأ أثناء التواصل مع المستشار الذكي. يرجى المحاولة لاحقاً.";
  }
};

