import { GoogleGenAI } from "@google/genai";
import { RIASECScores } from "../types";

// Function to get career guidance using the Gemini API based on user's RIASEC scores.
export const getCareerGuidance = async (scores: RIASECScores, userInput: string) => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    return "نظام الذكاء الاصطناعي غير مفعل حالياً. يرجى إضافة API_KEY في إعدادات Vercel.";
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = "gemini-3-flash-preview";

  const systemPrompt = `
    أنت مستشار مهني ذكي ورؤيوي في برنامج "بوصلتي".
    بناءً على نتائج RIASEC: R:${scores.R}, I:${scores.I}, A:${scores.A}, S:${scores.S}, E:${scores.E}, C:${scores.C}.
    أجب على أسئلة الطالب بذكاء، اربط إجاباتك بنقاط قوته، وقدم أمثلة واقعية من سوق العمل الخليجي والعربي الحديث.
    اجعل الحوار تفاعلياً وملهماً.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: userInput,
      config: {
        systemInstruction: systemPrompt,
      },
    });
    return response.text || "عذراً، لم أستطع تحليل البيانات حالياً.";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return "حدث خطأ أثناء التواصل مع المستشار الذكي.";
  }
};

export const getInitialAnalysis = async (scores: RIASECScores) => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return "أنت تمتلك مزيجاً فريداً من المهارات! ابدأ باستكشاف خياراتك المهنية.";

  const ai = new GoogleGenAI({ apiKey });
  const model = "gemini-3-flash-preview";

  const prompt = `
    بناءً على نتائج مقياس هولاند (RIASEC):
    الواقعي: ${scores.R}, البحثي: ${scores.I}, الفني: ${scores.A}, الاجتماعي: ${scores.S}, المغامر: ${scores.E}, التقليدي: ${scores.C}

    اكتب تقريراً مهنياً جذاباً للطالب (صف 11) يتكون من الأجزاء التالية:
    1. "هويتك المهنية": وصف ملهم يجمع بين أعلى نمطين لديه.
    2. "نقاط القوة": 3 نقاط قوة تميزه بناءً على درجاته العالية.
    3. "بيئة العمل المثالية": أين سيبدع؟ (ميدان، مكتب، مختبر، استوديو..).
    4. "تخصصات مقترحة": قائمة بـ 5 تخصصات جامعية حديثة تناسبه.

    اجعل الأسلوب منسقاً باستخدام عناوين واضحة ونقاط.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction: "أنت خبير توجيه مهني عالمي، لغتك عربية فصحى راقية ومحفزة جداً.",
      }
    });
    return response.text || "تحليل رائع بانتظارك!";
  } catch (error) {
    console.error("Initial Analysis Error:", error);
    return "أنت تمتلك مزيجاً فريداً من المهارات التي تميزك وتجعلك مستعداً لمستقبل واعد!";
  }
};

import React, { useState } from 'react';
import Layout from './components/Layout.tsx';
