            ></div>
          </div>
        </div>

        {QUESTIONS.map((q, idx) => (
          <div key={q.id} className={`bg-white p-8 rounded-[2.5rem] border transition-all duration-300 ${answers[q.id] ? 'border-emerald-100 shadow-sm opacity-60' : 'border-slate-100 shadow-md scale-100'}`}>
