                    className={`h-12 rounded-2xl text-lg font-black transition-all transform active:scale-90 ${answers[q.id] === val ? 'bg-emerald-600 text-white shadow-lg ring-4 ring-emerald-50' : 'bg-slate-50 text-slate-400 hover:bg-emerald-50 hover:text-emerald-600'}`}
                  >
