          <button onClick={() => setQuizStarted(true)} className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-5 rounded-[2rem] font-black text-xl transition-all shadow-2xl shadow-emerald-200 active:scale-95">ابدأ التقييم الآن</button>
        </div>
