    return (
      <div className="max-w-3xl mx-auto space-y-10 pb-32 animate-in fade-in duration-500 px-4">
        <div className="sticky top-24 z-40 bg-white/80 backdrop-blur-xl p-6 rounded-[2.5rem] border border-slate-100 shadow-xl mb-10">
          <div className="flex justify-between items-center mb-4">
            <span className="text-sm font-black text-slate-500">التقدم: {answeredCount} / {QUESTIONS.length}</span>
            <span className="px-3 py-1 bg-emerald-50 text-emerald-700 rounded-full text-xs font-black">{Math.round(progressPercent)}% مكتمل</span>
          </div>
          <div className="w-full h-3 bg-slate-100 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 to-teal-400 transition-all duration-700 ease-out" style={{ width: `${progressPercent}%` }}></div>
          </div>
        </div>

        {QUESTIONS.map((q, idx) => (
          <div key={q.id} className={`bg-white p-10 rounded-[3.5rem] border-2 transition-all duration-500 ${answers[q.id] ? 'border-emerald-100 shadow-sm opacity-60 scale-[0.98]' : 'border-slate-50 shadow-xl scale-100'}`}>
            <div className="flex gap-6 mb-10">
              <span className="w-10 h-10 rounded-2xl bg-slate-900 text-white flex items-center justify-center text-sm font-black shrink-0 shadow-lg">{idx + 1}</span>
              <p className="text-2xl font-black text-slate-800 leading-[1.4]">{q.text}</p>
