                {[1, 2, 3, 4, 5].map((val) => (
                  <button
                    key={val}
                    onClick={() => setAnswers(prev => ({ ...prev, [q.id]: val }))}
                    className={`h-16 rounded-2xl text-xl font-black transition-all transform active:scale-90 ${answers[q.id] === val ? 'bg-emerald-600 text-white shadow-xl shadow-emerald-200 ring-8 ring-emerald-50' : 'bg-slate-50 text-slate-400 hover:bg-emerald-50 hover:text-emerald-600 hover:shadow-inner'}`}
                  >
                    {val}
