export default App;

import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout.tsx';
import CareerChart from './components/CareerChart.tsx';
import { QUESTIONS, SESSIONS, RIASEC_INFO } from './constants.tsx';
import { RIASECScores, ChatMessage, RIASECKey, Session } from './types.ts';
import { getCareerGuidance, getInitialAnalysis } from './services/geminiService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('home');
  const [quizStarted, setQuizStarted] = useState(false);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [scores, setScores] = useState<RIASECScores | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState('');
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [currentInput, setCurrentInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages, isChatLoading]);

  const calculateResult = async () => {
    const newScores: RIASECScores = { R: 0, I: 0, A: 0, S: 0, E: 0, C: 0 };
    Object.entries(answers).forEach(([id, val]) => {
      const question = QUESTIONS.find(q => q.id === parseInt(id));
      if (question) {
        newScores[question.category] += val as number;
      }
    });
    setScores(newScores);
    setQuizStarted(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });

    const analysis = await getInitialAnalysis(newScores);
    setAiAnalysis(analysis);
  };

  const handleSendMessage = async () => {
    if (!currentInput.trim() || !scores) return;

    const userMsg: ChatMessage = { role: 'user', text: currentInput };
    setChatMessages(prev => [...prev, userMsg]);
    setCurrentInput('');
    setIsChatLoading(true);

    const botResponse = await getCareerGuidance(scores, currentInput);
    setChatMessages(prev => [...prev, { role: 'model', text: botResponse }]);
    setIsChatLoading(false);
  };

  const getSortedCategories = (scores: RIASECScores) => {
    return (Object.entries(scores) as [RIASECKey, number][])
      .sort(([, a], [, b]) => b - a);
  };

  const formatAiText = (text: string) => {
    return text.split('\n').map((line, i) => {
      if (line.startsWith('###') || line.startsWith('**')) {
        return <h4 key={i} className="text-xl font-black mt-6 mb-3 text-white">{line.replace(/[#*]/g, '')}</h4>;
      }
      if (line.startsWith('-') || line.startsWith('•')) {
        return <li key={i} className="mr-4 mb-2 list-none flex items-start gap-2">
          <span className="text-emerald-300 mt-1.5 w-1.5 h-1.5 rounded-full bg-current shrink-0"></span>
          {line.substring(1)}
        </li>;
      }
      return <p key={i} className="mb-2 opacity-90">{line}</p>;
    });
  };

