          <div className="mt-auto bg-slate-50 group-hover:bg-emerald-600 transition-colors duration-700 p-8 relative overflow-hidden">
            <div className="flex items-start gap-4 relative z-10">
              <div className="mt-1 w-8 h-8 rounded-full bg-emerald-100 group-hover:bg-white/20 flex items-center justify-center shrink-0 transition-colors">
                <svg className="w-4 h-4 text-emerald-600 group-hover:text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
